  async getDevices() {
    try {
      const devices = await navigator.mediaDevices.enumerateDevices()

      const microphones = []
      const speakers = []
      const cameras = []

      devices.forEach(device => {
        const label = device.label || `${device.kind} ${device.deviceId}`
        const deviceInfo = { 
